// DeepSeek returns OpenAI-shaped JSON. Pull the payload out and hand back clean data.
const out = [];
for (const item of $input.all()) {
  const raw = item.json?.choices?.[0]?.message?.content ?? '{}';
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    const s = raw.indexOf('{'), t = raw.lastIndexOf('}');
    parsed = s >= 0 ? JSON.parse(raw.slice(s, t + 1)) : { error: 'unparseable' };
  }
  out.push({ json: parsed });
}
return out;

// Gemini returns the image as inline base64. Hand back a data URL the browser can use directly.
const out = [];
for (const item of $input.all()) {
  const parts = item.json?.candidates?.[0]?.content?.parts || [];
  const img = parts.find(p => p.inlineData || p.inline_data);
  const data = img?.inlineData?.data || img?.inline_data?.data;
  const mime = img?.inlineData?.mimeType || img?.inline_data?.mime_type || 'image/png';
  out.push({ json: data ? { image: `data:${mime};base64,${data}` } : { error: 'no image returned' } });
}
return out;

// Turn the mp3 binary into a data URL so the browser can play it with no extra request.
const out = [];
for (const item of $input.all()) {
  const key = Object.keys(item.binary || {})[0];
  if (!key) { out.push({ json: { error: 'no audio returned' } }); continue; }
  const b = item.binary[key];
  out.push({ json: { audio: `data:audio/mpeg;base64,${b.data}` } });
}
return out;

const raw = $input.first().json?.choices?.[0]?.message?.content ?? '{}';
let brief;
try { brief = JSON.parse(raw); } catch (e) {
  const s = raw.indexOf('{'), t = raw.lastIndexOf('}');
  brief = s >= 0 ? JSON.parse(raw.slice(s, t + 1)) : {};
}
const traits = brief.traits || 'A round translucent gel creature with huge friendly eyes and thick dark eyebrows.';
const hat = (brief.headwear && brief.headwear.toLowerCase() !== 'none')
  ? ' It wears ' + brief.headwear + ', drawn as part of the same picture.' : '';
const prompt = 'Original character design. A single cartoon HEAD, front facing, perfectly centred, '
  + 'FILLING THE ENTIRE FRAME edge to edge with no margin and no empty space around it. '
  + traits + hat + ' '
  + 'Style: bold flat cartoon, thick confident outlines, large expressive features, strong saturated colours, '
  + 'high contrast, clearly readable at small size. Glossy jelly finish with one soft highlight. '
  + 'Background: pure solid black, absolutely nothing else on it. '
  + 'No neck, no shoulders, no body, no text, no logo, no border, no drop shadow. '
  + 'Original design only. Do not depict any existing character, mascot, franchise or trademarked figure.';
return [{ json: { prompt, traits, headwear: brief.headwear || 'none' } }];

// One place where the alert wording lives. Keep it a PROMPT TO CHECK, never a claim.
// This heuristic sees a movement pattern. It does not know what happened, and the
// message must not pretend otherwise.
const b = $input.first().json.body || {};
const who  = b.person ? b.person : 'the person Slime is with';
const when = b.at ? new Date(b.at).toLocaleString() : new Date().toLocaleString();
const text = [
  'Slime noticed something worth checking.',
  '',
  'Who: ' + who,
  'When: ' + when,
  'What was seen: ' + (b.contacts || '?') + ' fast hand-to-head movements in about '
    + (b.seconds || '?') + ' seconds.',
  '',
  'This is a movement pattern picked up by a camera, not a diagnosis. It has ordinary',
  'explanations too. Please check in when you can.'
].join('\n');
return [{ json: { text, chatId: b.chatId || '', person: who, at: when } }];
